<script setup lang="ts">
import {ref,reactive,watch,onBeforeUnmount,computed,nextTick} from 'vue'
import AppIcon from '@/components/common/AppIcon.vue'
import {apiRequest} from '@/api/client'
import {createUuid} from '@/utils/id'
import type {WorkspaceRoutine,WorkspaceRoutineRun,WorkspaceSchedule} from '@shared/workspacePanels'
const props=defineProps<{agentId:string;editorOnly?:boolean}>()
const emit=defineEmits<{changed:[];executed:[id:string]}>()
const routines=ref<WorkspaceRoutine[]>([]),runs=ref<WorkspaceRoutineRun[]>([]),editing=ref<string|null>(null),showEditor=ref(false),error=ref(''),busy=ref(false)
const hosts=ref<{id:string;name:string}[]>([])
const form=reactive({deviceHost:'',name:'',prompt:'',enabled:true,kind:'daily' as WorkspaceSchedule['kind'],time:'09:00',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,everyMinutes:60,at:'',weekdays:[1,2,3,4,5]})
const status:Record<string,string>={queued:'排队中',running:'执行中',waiting:'等待处理',complete:'已完成',failed:'失败',interrupted:'已停止',uncertain:'状态待确认',skipped:'已跳过'}
const view=ref<'list'|'logs'>('list'),logFilter=ref(''),query=ref(''),statusFilter=ref('all'),dialog=ref<HTMLDialogElement>()
const sorted=computed(()=>[...routines.value].sort((a,b)=>Number(b.enabled)-Number(a.enabled)||(a.nextAt??Infinity)-(b.nextAt??Infinity)||a.name.localeCompare(b.name)))
const selectedRoutine=computed(()=>routines.value.find(r=>r.id===editing.value))
const logs=computed(()=>runs.value.filter(r=>(!logFilter.value||r.routineId===logFilter.value)&&(statusFilter.value==='all'||r.status===statusFilter.value)&&(routines.value.find(item=>item.id===r.routineId)?.name+' '+(r.error??'')).toLowerCase().includes(query.value.trim().toLowerCase())))
const date=(at?:number)=>at?new Date(at).toLocaleString('zh-CN',{hour12:false}):''
const latest=(id:string)=>runs.value.find(r=>r.routineId===id)
const scheduleLabel=(r:WorkspaceRoutine)=>r.schedule.kind==='interval'?`每 ${r.schedule.everyMinutes} 分钟`:r.schedule.kind==='once'?date(r.schedule.at):`${r.schedule.kind==='weekly'?'每周 '+(r.schedule.weekdays??[]).map(i=>'日一二三四五六'[i]).join('、'):'每天'} ${r.schedule.time}`
const scheduleState=(r:WorkspaceRoutine)=>r.enabled?'已启用':r.schedule.kind==='once'&&r.lastAt?'已结束':'已暂停'
function openLogs(id=''){logFilter.value=id;view.value='logs';query.value='';statusFilter.value='all'}
watch(showEditor,async(value)=>{await nextTick();if(value)dialog.value?.showModal();else dialog.value?.close()})
async function runNow(r:WorkspaceRoutine){await action(async()=>{await apiRequest(base()+'/'+r.id+'/run',{method:'POST',body:{requestId:createUuid()}});showEditor.value=false;openLogs(r.id);emit('executed',r.id)})}
let timer:ReturnType<typeof setTimeout>|undefined,closed=false,generation=0
const base=()=>`/api/app/agents/${props.agentId}/routines`
async function load(){const version=generation;try{const value=await apiRequest<{routines:WorkspaceRoutine[];runs:WorkspaceRoutineRun[]}>(base());if(version===generation&&!closed){routines.value=value.routines;runs.value=value.runs;error.value=''}}catch(e){if(version===generation&&!closed)error.value=e instanceof Error?e.message:'无法读取定时任务'}}
async function cycle(){const version=generation;if(!document.hidden&&!busy.value)await load();if(!closed&&version===generation)timer=setTimeout(cycle,5000)}
let editorGeneration=0
async function edit(r?:WorkspaceRoutine){const version=++editorGeneration,agentId=props.agentId;editing.value=r?.id??null;Object.assign(form,{deviceHost:r?.deviceHost??'',name:r?.name??'',prompt:r?.prompt??'',enabled:r?.enabled??true,kind:r?.schedule.kind??'daily',time:r?.schedule.time??'09:00',timezone:r?.schedule.timezone??Intl.DateTimeFormat().resolvedOptions().timeZone,everyMinutes:r?.schedule.everyMinutes??60,at:r?.schedule.at?new Date(r.schedule.at-new Date(r.schedule.at).getTimezoneOffset()*60000).toISOString().slice(0,16):'',weekdays:r?.schedule.weekdays??[1,2,3,4,5]});showEditor.value=true;try{const [result,source]=await Promise.all([apiRequest<{hosts:{id:string;name:string}[]}>(`/api/app/agents/${agentId}/desktop-environment`),r?Promise.resolve(undefined):window.yaoyaoDesktop?.deviceHost?.()]);if(version!==editorGeneration||agentId!==props.agentId||closed)return;hosts.value=result.hosts;if(!r&&!form.deviceHost)form.deviceHost=source?.deviceHost??''}catch{if(version===editorGeneration)hosts.value=[]}}
async function action(work:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';try{await work();await load();emit('changed')}catch(e){error.value=e instanceof Error?e.message:'定时任务操作失败'}finally{busy.value=false}}
function payload(r:WorkspaceRoutine){return {name:r.name,prompt:r.prompt,enabled:!r.enabled,deviceHost:r.deviceHost??null,schedule:r.schedule}}
async function save(){const original=selectedRoutine.value?.schedule.at,originalDisplay=original?new Date(original-new Date(original).getTimezoneOffset()*60000).toISOString().slice(0,16):undefined;const schedule:WorkspaceSchedule={kind:form.kind,timezone:form.timezone,...(form.kind==='once'?{at:originalDisplay===form.at?original:new Date(form.at).getTime()}:form.kind==='interval'?{everyMinutes:form.everyMinutes}:{time:form.time,...(form.kind==='weekly'?{weekdays:form.weekdays}:{})})};await action(async()=>{await apiRequest(base()+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:{name:form.name,prompt:form.prompt,enabled:form.enabled,deviceHost:form.deviceHost||null,schedule} as any});showEditor.value=false})}
watch(()=>props.agentId,()=>{generation++;routines.value=[];runs.value=[];showEditor.value=false;view.value='list';logFilter.value='';clearTimeout(timer);if(!props.editorOnly)void cycle()},{immediate:true})
defineExpose({edit:(r?:WorkspaceRoutine)=>{if(props.editorOnly)routines.value=r?[r]:[];edit(r)}})
onBeforeUnmount(()=>{closed=true;generation++;clearTimeout(timer)})
</script>
<template>
 <section v-show="!editorOnly" class="routines" aria-label="机器人定时任务">
  <template v-if="view==='list'">
   <div class="routine-overview"><div class="overview-title"><AppIcon name="calendar" :size="16"/><h2>定时任务</h2><span>{{routines.length}}</span></div><div class="overview-actions"><button class="primary" @click="edit()"><AppIcon name="plus" :size="14"/>新建定时任务</button><button @click="openLogs()"><AppIcon name="file" :size="13"/>运行日志</button></div></div>
   <p v-if="error" class="error-box" role="alert">{{error}}</p>
   <div v-if="!routines.length" class="empty-state"><AppIcon name="calendar" :size="22"/><p>还没有定时任务</p><small>为这个机器人安排定期执行的工作。</small></div>
   <article v-for="routine in sorted" :key="routine.id" class="routine-card" :aria-label="routine.name">
    <div class="card-heading"><button class="routine-title" @click="edit(routine)"><h3>{{routine.name}}</h3><span>{{scheduleLabel(routine)}} · {{routine.schedule.timezone}}</span></button><span :class="['state-pill',{enabled:routine.enabled}]">{{scheduleState(routine)}}</span></div>
    <p v-if="routine.enabled&&routine.nextAt" class="next-run">下次 {{date(routine.nextAt)}}</p>
    <div class="latest-row"><div v-if="latest(routine.id)"><span :class="{failure:latest(routine.id)?.status==='failed'}">最近执行：{{status[latest(routine.id)!.status]}}</span><small>{{date(latest(routine.id)!.startedAt)}}</small></div><span v-else class="muted">尚未执行</span><button :aria-label="'查看'+routine.name+'的运行日志'" @click="openLogs(routine.id)"><AppIcon name="file" :size="12"/>日志</button></div>
    <p v-if="latest(routine.id)?.error" class="result-preview failure">{{latest(routine.id)!.error}}</p>
   </article>
  </template>
  <template v-else>
   <div class="logs-heading"><button class="back" aria-label="返回定时任务列表" @click="view='list'"><AppIcon name="chevron-left" :size="16"/></button><div><h2>运行日志</h2><p>查看每次执行的状态与结果。</p></div></div>
   <div class="log-filters"><label><AppIcon name="search" :size="14"/><input v-model="query" aria-label="搜索运行日志" placeholder="搜索任务或错误"></label><select v-model="statusFilter" aria-label="筛选执行状态"><option value="all">全部状态</option><option v-for="(label,key) in status" :key="key" :value="key">{{label}}</option></select></div>
   <div v-if="logFilter" class="scope-hint">当前任务的日志<button @click="logFilter=''">显示全部</button></div>
   <p v-if="error" class="error-box" role="alert">{{error}}</p>
   <div v-if="!logs.length" class="empty-state"><AppIcon name="file" :size="24"/><p>{{runs.length?'没有匹配的执行记录':'还没有执行记录'}}</p></div>
   <details v-for="run in logs" :key="run.id" class="run-card"><summary><div><strong>{{routines.find(r=>r.id===run.routineId)?.name??'定时任务'}}</strong><small>{{date(run.startedAt)}} · {{run.scheduledAt===0?'手动执行':'定时执行'}}</small></div><span :class="['run-state',{failure:run.status==='failed',success:run.status==='complete'}]">{{status[run.status]??run.status}}</span></summary><p v-if="run.error" class="failure">{{run.error}}</p><p v-else>{{run.status==='complete'?'结果已发送到机器人的聊天。':'执行进度会自动更新。'}}</p><RouterLink v-if="run.conversationId" :to="'/conversations/'+run.conversationId">查看聊天结果 ↗</RouterLink></details>
  </template>
  <Teleport to="body"><dialog v-if="showEditor" ref="dialog" class="routine-editor" :aria-label="editing?'编辑定时任务':'新建定时任务'" @cancel.prevent="showEditor=false">
   <form @submit.prevent="save"><header><div><AppIcon name="calendar" :size="18"/><h2>{{editing?'编辑定时任务':'新建定时任务'}}</h2></div><button type="button" class="icon-button" aria-label="关闭定时任务编辑器" @click="showEditor=false"><AppIcon name="close"/></button></header>
    <div class="editor-body"><p v-if="error" class="error-box" role="alert">{{error}}</p><label>任务中的“本机”<select v-model="form.deviceHost"><option value="">未指定，请在任务中点名目标电脑</option><option v-for="host in hosts" :key="host.id" :value="host.id">{{host.id==='local'?'服务器 · ':''}}{{host.name}}</option><option v-if="form.deviceHost&&!hosts.some(h=>h.id===form.deviceHost)" :value="form.deviceHost">原设备（未连接）</option></select><small>固定使用保存的目标，不随查看任务的客户端变化。</small></label><label>名称<input v-model="form.name" required maxlength="100" placeholder="为这项工作命名"></label><label>任务内容<textarea v-model="form.prompt" required maxlength="24000" rows="5" placeholder="告诉机器人需要定期完成什么"/></label>
     <div class="schedule-grid"><label>重复<select v-model="form.kind" aria-label="重复"><option value="once">仅一次</option><option value="interval">固定间隔</option><option value="daily">每天</option><option value="weekly">每周</option></select></label><label v-if="form.kind==='once'">执行时间<input v-model="form.at" type="datetime-local" required></label><label v-else-if="form.kind==='interval'">间隔（分钟）<input v-model.number="form.everyMinutes" type="number" min="1" max="525600" required></label><label v-else>执行时间<input v-model="form.time" type="time" required></label></div>
     <fieldset v-if="form.kind==='weekly'"><legend>每周</legend><label v-for="(day,index) in ['日','一','二','三','四','五','六']" :key="day" class="check"><input v-model="form.weekdays" type="checkbox" :value="index">{{day}}</label></fieldset><label>时区<input v-model="form.timezone" required placeholder="Asia/Shanghai"></label><p class="editor-note">服务端按计划执行，结果回到当前机器人的聊天。</p>
    </div>
    <footer><div class="secondary-actions" v-if="selectedRoutine"><button type="button" :disabled="busy" @click="runNow(selectedRoutine)">立即执行</button><button type="button" :disabled="busy" @click="action(async()=>{await apiRequest(base()+'/'+selectedRoutine!.id,{method:'PUT',body:payload(selectedRoutine!) as any});showEditor=false})">{{selectedRoutine.enabled?'暂停':'启用'}}</button><button type="button" class="danger-button" :disabled="busy" @click="action(async()=>{await apiRequest(base()+'/'+selectedRoutine!.id,{method:'DELETE'});showEditor=false})">删除</button></div><div class="save-actions"><button type="button" :disabled="busy" @click="showEditor=false">取消</button><button class="primary" :disabled="busy">保存</button></div></footer>
   </form>
  </dialog></Teleport>
 </section>
</template>
<style scoped>
.routines{padding:16px;overflow:auto;min-height:0;display:flex;flex-direction:column;gap:14px;color:var(--text-primary)}.routine-overview{border-radius:12px;background:var(--surface-raised);padding:16px}.overview-title,.overview-actions,.card-heading,.latest-row,.logs-heading,.log-filters{display:flex;align-items:center;gap:8px}.overview-title .app-icon{color:var(--accent)}h2{font-size:15px;font-weight:600;margin:0}.overview-title h2{flex:1}.overview-title>span{font-size:11.5px;color:var(--text-muted)}.overview-actions{margin-top:14px}.overview-actions .primary{flex:1}button,input,select,textarea{font:inherit;color:inherit;border:1px solid var(--line);border-radius:8px;background:var(--surface-raised);box-sizing:border-box;min-height:40px;min-width:0;padding:8px 10px;font-size:12px}button{cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px}button:disabled{opacity:.5;cursor:default}.primary{background:var(--accent);border-color:var(--accent);color:var(--text-on-solid);font-weight:500}.routine-card,.run-card{border:1px solid var(--line);border-radius:12px;background:var(--surface-raised);padding:14px}.card-heading{align-items:flex-start}.routine-title{flex:1;min-width:0;text-align:left;display:block;padding:0;border:0;background:transparent;min-height:40px}.routine-title h3{font-size:13px;line-height:1.5;font-weight:600;margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.routine-title span{display:block;font-size:11.5px;line-height:1.7;color:var(--text-muted);margin-top:4px}.state-pill{flex:none;border-radius:999px;padding:3px 8px;font-size:10px;line-height:1.5;background:var(--surface-soft);color:var(--text-muted)}.state-pill.enabled{color:var(--accent)}.next-run{font-size:11.5px;color:var(--text-muted);margin:10px 0 6px}.latest-row{justify-content:space-between;font-size:11.5px;align-items:flex-start;margin-top:8px}.latest-row small{display:block;font-size:10.5px;color:var(--text-muted);margin-top:5px}.latest-row button{font-size:11px;min-height:32px;padding:5px 7px;border:0;background:transparent;color:var(--text-secondary)}.result-preview{font-size:11.5px;line-height:1.6;margin-bottom:0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.muted{color:var(--text-muted)}.empty-state{padding:28px 18px;border:1px dashed var(--line);border-radius:12px;text-align:center;color:var(--text-muted)}.empty-state .app-icon{opacity:.6}.empty-state p{font-size:13px}.empty-state small{font-size:11.5px}.logs-heading{align-items:flex-start}.logs-heading h2{font-size:17px}.logs-heading p{font-size:12px;color:var(--text-muted);margin:6px 0}.back{min-width:36px;min-height:36px;padding:6px;border:0;background:transparent}.log-filters{flex-wrap:wrap}.log-filters label{display:flex;align-items:center;gap:6px;flex:1;min-width:150px;padding:0 10px;border:1px solid var(--line);border-radius:8px;color:var(--text-muted)}.log-filters input{width:100%;border:0;padding-left:0;background:transparent}.scope-hint{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--text-muted)}.scope-hint button{border:0;color:var(--accent);background:transparent}.run-card summary{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;cursor:pointer;min-height:44px;list-style:none}.run-card summary::-webkit-details-marker{display:none}.run-card strong{display:block;font-size:13px}.run-card small{display:block;font-size:11px;line-height:1.6;color:var(--text-muted);margin-top:5px}.run-state{flex:none;font-size:11.5px}.failure,.error-box{color:var(--danger)}.success{color:var(--success,var(--accent))}.run-card p{font-size:12px;line-height:1.7}.run-card a{font-size:12px;color:var(--accent)}.error-box{font-size:12px;line-height:1.6;padding:10px;border-radius:8px;background:color-mix(in srgb,var(--danger) 8%,transparent)}.routine-editor{width:min(640px,calc(100vw - 32px));max-height:92dvh;padding:0;border:1px solid var(--line);border-radius:16px;background:var(--surface);color:var(--text-primary);box-shadow:0 24px 100px #0005;overflow:auto}.routine-editor::backdrop{background:#0008;backdrop-filter:blur(3px)}.routine-editor header,.routine-editor footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 22px;border-bottom:1px solid var(--line)}.routine-editor header>div{display:flex;align-items:center;gap:10px}.icon-button{border:0;background:transparent;min-width:40px}.editor-body{display:grid;gap:18px;padding:22px}.editor-body label{display:grid;gap:8px;font-size:12px;font-weight:500}.editor-body textarea{resize:vertical;line-height:1.7}.schedule-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.editor-body input,.editor-body textarea,.editor-body select{width:100%;font-size:13px;min-height:44px}.editor-note{font-size:11.5px;color:var(--text-muted);margin:0}.routine-editor footer{border-bottom:0;border-top:1px solid var(--line);flex-wrap:wrap}.save-actions,.secondary-actions{display:flex;gap:8px}.save-actions{margin-left:auto}.danger-button{color:var(--danger)}fieldset{border:1px solid var(--line);border-radius:8px;display:flex;gap:10px;flex-wrap:wrap}.editor-body .check{display:flex;align-items:center;gap:4px;min-height:44px}.check input{width:16px;min-height:16px}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:2px}@media(max-width:600px){button{min-height:44px}.latest-row button{min-height:44px}.routine-editor{width:calc(100vw - 20px)}.editor-body{padding:16px}.routine-editor header,.routine-editor footer{padding:14px 16px}.schedule-grid{grid-template-columns:1fr}.routines{gap:12px}}
</style>
